func pageControlFilterHref(key string) string {
	if key == "" {
		return "/admin/system-pages"
	}
	return "/admin/system-pages?resource=" + key
}

func pageControlCount(v SystemPagesView, key string) int {
	if key == "" {
		return v.Total
	}
	return v.Counts[key]
}

func pageControlResourceLabel(key string) string {
	for _, r := range pageControlResources {
		if r.Key == key {
			return r.Label
		}
	}
	return key
}

